questions.questionText:
¿Qué valor tiene idx al final?
int[] a = { 4, 8, 15, 16, 23 };
int idx = -1;
for (int i = 0; i < a.Length; i++)
{
    if (a[i] > 10)
    {
        idx = i;
        break;
    }
}
Console.Write(idx);

